contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(deposit > 0, "deposit must be positive");
        require(address(this).balance >= deposit, "insufficient balance");

        uint beforeContract = address(c).balance;
        uint beforeCaller = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        c.addToBalance{value: deposit}(); if (__ESBMC_reverted()) return;

        uint recordedBeforeWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint contractBeforeWithdraw = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterContract = address(c).balance;
        uint afterCaller = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(
            (recordedBeforeWithdraw == beforeCaller + deposit) &&
            (
                (reverted && afterContract == contractBeforeWithdraw && afterCaller == recordedBeforeWithdraw) ||
                (!reverted && afterContract + recordedBeforeWithdraw == contractBeforeWithdraw && afterCaller == 0)
            )
        );
    }

    receive() external payable {}
}

