// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(deposit > 0);
        vm.assume(address(this).balance >= deposit);
        uint beforeContract = address(c).balance;
        uint256 beforeCaller;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeCaller = __r; } catch { return; }
        try c.addToBalance{value: deposit}() {} catch { return; }
        uint256 recordedBeforeWithdraw;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedBeforeWithdraw = __r; } catch { return; }
        uint contractBeforeWithdraw = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterContract = address(c).balance;
        uint256 afterCaller;
        try c.getBalance(address(this)) returns (uint256 __r) { afterCaller = __r; } catch { return; }
        assertTrue((recordedBeforeWithdraw == beforeCaller + deposit) &&
            (
                (reverted && afterContract == contractBeforeWithdraw && afterCaller == recordedBeforeWithdraw) ||
                (!reverted && afterContract + recordedBeforeWithdraw == contractBeforeWithdraw && afterCaller == 0)
            ));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
